// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 depositAmount, uint256 firstWithdraw, uint256 secondWithdraw) public {
        vm.assume(depositAmount > 0);
        firstWithdraw = bound(firstWithdraw, 0, depositAmount - 1);
        secondWithdraw = bound(secondWithdraw, 0, depositAmount - firstWithdraw);
        address actor = address(0xABCD);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        vm.prank(actor);
        c.withdraw(firstWithdraw);
        // Rule: a partial withdrawal of firstWithdraw < depositAmount leaves
        // depositAmount - firstWithdraw withdrawable; a second withdrawal of any
        // amount within the remainder must not revert.
        bool ok;
        vm.prank(actor);
        try c.withdraw(secondWithdraw) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
